package main

// A small, self-contained reader for the flat JSON/YAML secret documents
// accepted by import. Parsing is separated from conversion so type errors carry
// the line and column of the value rather than the containing object.
import (
    "encoding/json"
    "errors"
    "fmt"
    "io"
    "strconv"
    "strings"
    "unicode"
)

type yamlNode struct {kind,text,typ string;pos,end int;pairs []yamlPair;items []*yamlNode}
type yamlPair struct{key,value *yamlNode}
type yamlReader struct{src string;lines []string;offsets []int;i int;anchors map[string]*yamlNode}
func parseSecrets(data []byte)(map[string]string,error){
    source:=strings.TrimPrefix(string(data),"\ufeff")
    p:=&yamlReader{src:source,anchors:map[string]*yamlNode{}}
    p.lines=strings.Split(strings.TrimRight(source,"\r\n"),"\n");off:=0
    for _,line:=range p.lines{p.offsets=append(p.offsets,off);off+=len(line)+1}
    line:=0;for line<len(p.lines){t:=strings.TrimSpace(p.lines[line]);if t==""||strings.HasPrefix(t,"#")||t=="---"{line++;continue};break}
    if line>=len(p.lines){return nil,io.EOF}
    root,next,err:=p.block(line,indentation(p.lines[line]));if err!=nil{return nil,err}
    for next<len(p.lines){t:=strings.TrimSpace(p.lines[next]);if t=="---"||t=="..."{break};if t!=""&&!strings.HasPrefix(t,"#"){return nil,p.failure(p.offsets[next]+indentation(p.lines[next]),"value is not allowed in this context")};next++}
    if root==nil||root.kind=="scalar"&&root.typ=="null"{return nil,io.EOF}
    if root.kind!="map" {typ:=root.typ;if root.kind=="seq"{typ="sequence"};return nil,p.failure(root.pos,typ+" was used where mapping is expected")}
    result:=map[string]string{}
    for _,pair:=range root.pairs{
        k:=pair.key.text;v:=pair.value
