    if strings.HasPrefix(last,"-")&&in.dash<0{
        defs:=defsFor(cmd);if cmd==""{sort.Slice(defs,func(i,j int)bool{return defs[i].name<defs[j].name})}
        if strings.Contains(last,"="){finish(0);return 0}
        for _,d:=range defs{if in.changed[d.name]&&d.kind!="map"{continue};name:="--"+d.name;if strings.HasPrefix(name,last){emit(name,d.description)};if d.short!=""{name="-"+d.short;if strings.HasPrefix(name,last){emit(name,d.description)}}}
        finish(4);return 0
    }
    if len(commands[cmd].children)>0&&len(in.args)==0{
        for _,child:=range commands[cmd].children{name:=child;if i:=strings.LastIndex(name," ");i>=0{name=name[i+1:]};if strings.HasPrefix(name,last){emit(name,commands[child].description)}};finish(4);return 0
