func complete(tokens []string,noDesc bool)int{
    last:=tokens[len(tokens)-1];before:=tokens[:len(tokens)-1]
    cmd,rest,err:=findCommand(before)
    finish:=func(d int){fmt.Printf(":%d\n",d);name:="ShellCompDirectiveDefault";if d==4{name="ShellCompDirectiveNoFileComp"};fmt.Fprintln(os.Stderr,"Completion ended with directive:",name)}
    if err!=nil{fmt.Fprintf(os.Stderr,"[Debug] [Error] unable to find a command for arguments: [%s]\n",strings.Join(before," "));finish(0);return 0}
    // A value-taking flag immediately before the word being completed.
    if len(rest)>0{
        t:=rest[len(rest)-1];defs:=defsFor(cmd)
        if strings.HasPrefix(t,"--")&&!strings.Contains(t,"="){if d,ok:=defByName(defs,t[2:],false);ok&&d.kind!="bool"{finish(0);return 0}}
        if len(t)==2&&t[0]=='-'{if d,ok:=defByName(defs,t[1:],true);ok&&d.kind!="bool"{finish(0);return 0}}
    }
    in,err:=parseInvocation(cmd,rest);if err!=nil{fmt.Fprintf(os.Stderr,"[Debug] [Error] Error while parsing flags from args [%s]: %v\n",strings.Join(rest," "),err);finish(0);return 0}
    emit:=func(value,description string){if noDesc||description==""{fmt.Println(value)}else{fmt.Printf("%s\t%s\n",value,description)}}
    if strings.HasPrefix(last,"-")&&in.dash<0{
        defs:=defsFor(cmd);if cmd==""{sort.Slice(defs,func(i,j int)bool{return defs[i].name<defs[j].name})}
        if strings.Contains(last,"="){finish(0);return 0}
        for _,d:=range defs{if in.changed[d.name]&&d.kind!="map"{continue};name:="--"+d.name;if strings.HasPrefix(name,last){emit(name,d.description)};if d.short!=""{name="-"+d.short;if strings.HasPrefix(name,last){emit(name,d.description)}}}
        finish(4);return 0
    }
    if len(commands[cmd].children)>0&&len(in.args)==0{
        for _,child:=range commands[cmd].children{name:=child;if i:=strings.LastIndex(name," ");i>=0{name=name[i+1:]};if strings.HasPrefix(name,last){emit(name,commands[child].description)}};finish(4);return 0
    }
    if cmd=="help" {
        for _,child:=range commands[""].children{if strings.HasPrefix(child,last){emit(child,commands[child].description)}};finish(4);return 0
    }
