    initCommands()
    tests:=[]struct{args []string;cmd string;count int;errorText string}{
        {[]string{"-b","null","list","service","-etu"},"list",1,""},
        {[]string{"read","service","key","--version=0x10"},"read",2,""},
        {[]string{"read","-v","08"},"read",0,`invalid argument "08" for "-v, --version" flag`},
        {[]string{"env","service","-ev"},"env",1,`unknown shorthand flag: 'v' in -v`},
        {[]string{"exec","a","b","--","echo","--help"},"exec",4,""},
        {[]string{"tag","write","s","k","a=b"},"tag write",3,""},
    }
    for _,tt:=range tests {
        cmd,args,err:=findCommand(tt.args)
        if err!=nil{t.Fatal(err)}
        if cmd!=tt.cmd{t.Errorf("%v: command %q",tt.args,cmd)}
        in,err:=parseInvocation(cmd,args)
        if tt.errorText!="" {if err==nil||!strings.Contains(err.Error(),tt.errorText){t.Errorf("%v: error %v",tt.args,err)};continue}
        if err!=nil{t.Fatal(err)}
        if len(in.args)!=tt.count{t.Errorf("%v: arguments %v",tt.args,in.args)}
    }
}
